new:
var subtitle = ExteraPreferences.standard.value(for: ExteraSettings.hidePhoneNumber) ? "" : formatPhoneNumber(context: self.context, number: user.phone ?? "")

if let mainUsername = user.addressName, !mainUsername.isEmpty {
    subtitle = subtitle.isEmpty ? "@\(mainUsername)" : "\(subtitle) • @\(mainUsername)"
}

override public func viewDidAppear(_ animated: Bool) {
    super.viewDidAppear(animated)
    // Local display preferences may have changed in the pushed settings screen.
    if let (layout, navigationHeight) = self.validLayout {
        self.controllerNode.containerLayoutUpdated(layout: layout, navigationHeight: navigationHeight, transition: .immediate)
    }
